<script lang="ts">import {statusClass,statusText} from '../lib/workflow';import type {LifecycleStage} from '../lib/model/entityTypes';export let stages:LifecycleStage[]=[];export let currentStage='';</script>
<div class="workflow-timeline" data-testid="workflow-timeline" data-current-stage={currentStage}>{#each stages as stage,i}<div class:current={stage.id===currentStage} class:completed={stage.status==='COMPLETE'||stage.status==='PASS'} class:blocked={stage.status==='BLOCKED'} class="workflow-stage"><span class="stage-dot {statusClass(stage.status)}">{stage.status==='COMPLETE'||stage.status==='PASS'?'✓':i+1}</span><div><strong>{stage.label}</strong><small>{stage.id}</small><em>{statusText(stage.status)}</em></div></div>{/each}</div>
